"""S1 第一步：盤點既有短線個股選股規則（只讀各資料夾 results.json／FINDINGS.md，不重算）。
用法：python3 -I -B leaderboard_build.py   → leaderboard.csv
數字來源：各資料夾 results.json 的驗證期 2019-05～2026-10、一般成本（來回約 0.67%）欄位；json 沒有的欄位取自該資料夾 FINDINGS.md 的文字，
兩處都沒有的寫「未報」。成本、資金口徑各題不同，排行榜只用來挑候選。"""
import json, re, csv
from pathlib import Path
AG = Path(__file__).resolve().parent.parent
OUT = Path(__file__).resolve().parent / 'leaderboard.csv'
YEARS = 7.48          # 2019-05-01～2026-10-22
RT = 0.67             # 原各題來回成本（%）；當沖 0.23

def walk(d, path, out):
    if isinstance(d, dict):
        if any(k in d for k in ('CAGR', 'mean_raw_pct', 'mean_net_pct')):
            out.append((path, d))
        for k, v in d.items():
            walk(v, path + [str(k)], out)

_cache = {}
def variants(folder):
    if folder in _cache:
        return _cache[folder]
    d = json.load(open(AG / folder / 'results.json')); d.pop('PREREG', None)
    out = []; walk(d, [], out); var = {}
    for p, x in out:
        s = '/'.join(p)
        if not re.search(r'valid(_all)?_2019-05_2026-10(_incl_src3)?$|/valid$|valid_incl_src3_2019-05_2026-10$', s):
            continue
        if re.search(r'EW_|/0\.0/|0\.005|stress|gross|bench|judgement|slip0\.0/|cost_0\.0/|cost_0\.005', s):
            continue
        key = '/'.join(t for t in p if not re.search(r'^(results|RESULTS|events?|portfolio|portfolios|windows|0\.001|cost_0\.001|slip0\.001|normal|port_.*|event_.*|valid.*|monthly)$', t))
        v = var.setdefault(key, {})
        for k, nk in (('n', 'n'), ('avg_hold_days', 'hold'), ('mean_hold_days', 'hold'), ('hold_days', 'hold'), ('mean_raw_pct', 'raw'), ('mean_net_pct', 'net'),
                      ('mean_ab_gross_pct', 'abg'), ('t_month_ab_gross', 't_abg'), ('CAGR', 'cagr'), ('0050_CAGR', 'c0050'), ('maxDD', 'mdd')):
            if x.get(k) is not None and nk not in v:
                v[nk] = x[k]
    _cache[folder] = var
    return var

